// gen-all-missing.cjs — Generate ALL 175 missing substance cards
const fs = require("fs");
let catalog = fs.readFileSync("src/data/support-catalog.ts", "utf-8");
const insertPos = catalog.lastIndexOf("};");
let cards = "";

function a(id, name, nameRu, tier, cats, organs, systems, mechs, desc, mg, timing, form, bestFor, mon, co, se, forms) {
  const catArr = cats.split(",");
  const orgArr = organs.split(",");
  const sysArr = systems.split(",");
  const mechArr = mechs.split(",");
  const formsInput = Array.isArray(forms) ? forms : (typeof forms === 'string' ? [forms] : [nameRu + ' ' + (mg >= 1000 ? (mg/1000) + ' г' : mg < 1 ? (mg*1000) + ' мкг' : mg + ' мг')]);
  const monArr = (mon || "").split(",").filter(Boolean).map(m => { const p = m.split("|"); return "      { what: '" + p[0] + "', when: '" + p[1] + "'" + (p[2] ? ", targetRange: '" + p[2] + "'" : "") + " }"; });
  const coArr = (co || "").split(",").filter(Boolean);
  const seArr = (se || "").split(",").filter(Boolean);
  const fStr = formsInput.map((f, i) => "      { id: '" + id + (i > 0 ? "_" + (i+1) : "") + "', name: '" + name + "', nameRu: '" + f + "', dose: '" + (mg >= 1000 ? (mg/1000).toFixed(1).replace(".0","") + " г" : mg < 1 ? (mg*1000) + " мкг" : mg + " мг") + (i === 0 ? " 2x/д" : "") + "', best: " + (i === 0) + " }").join(",\n");
  cards += "  " + id + ": {\n    id: '" + id + "',\n    name: '" + name + "',\n    nameRu: '" + nameRu + "',\n    tier: '" + tier + "',\n    category: [" + catArr.map(c => "'" + c + "'").join(", ") + "],\n    forms: [\n" + fStr + "\n    ],\n    organs: [" + orgArr.map(o => "'" + o + "'").join(", ") + "],\n    systems: [" + sysArr.map(s => "'" + s + "'").join(", ") + "],\n    mechanisms: [" + mechArr.map(m => "'" + m + "'").join(", ") + "],\n    description: '" + desc + "',\n    synergies: [],\n    conflicts: [],\n    monitoring: [\n" + monArr.join(",\n") + "\n    ],\n    contraindications: [" + coArr.map(c => "'" + c + "'").join(", ") + "],\n    sideEffects: [" + seArr.map(s => "'" + s + "'").join(", ") + "],\n    dosage: { mg: " + mg + ", timing: '" + timing + "', form: '" + form + "' },\n    bestForCourse: " + bestFor + ",\n  },\n";
}

